using R_Half = std::ratio<1, 2>;
using R_Quarter = std::ratio<1, 4>;

// Access numerator and denominator
constexpr long long N = R_Half::num; // N = 1
constexpr long long D = R_Half::den; // D = 2

// Arithmetic operations (Result is always normalized/reduced)
using R_Add = std::ratio_add<R_Half, R_Quarter>;   // 3/4
using R_Mult = std::ratio_multiply<R_Half, R_Half>; // 1/4

// Comparison
static_assert(R_Add::num == 3 && R_Add::den == 4);
static_assert(std::ratio_equal<R_Half, R_Mult>::value == false);
static_assert(std::ratio_greater<R_Add, R_Mult>::value);
